        public static ContentChip[] Chips()
        {
            var chips=Raw();var all=chips.Concat(NativeRoundsCards.Chips()).ToArray();
            foreach(var c in chips)if(!string.IsNullOrEmpty(c.mechanic))
                c.excludes=new[]{c.mechanic}.Concat(all.Where(other=>other.id!=c.id&&other.mechanic==c.mechanic).Select(other=>other.id)).Distinct(StringComparer.Ordinal).OrderBy(id=>id,StringComparer.Ordinal).ToArray();
            return chips;
        }
        public static string[] Selection(IEnumerable<string> selected)
        {
            var ids=(selected??Array.Empty<string>()).ToArray();
            if(ids.Length>Ids.Length||ids.Any(id=>id==null||!Ids.Contains(id))||ids.Distinct(StringComparer.Ordinal).Count()!=ids.Length)throw new ArgumentException("Invalid bundled pack selection");
            return ids.OrderBy(id=>id,StringComparer.Ordinal).ToArray();
        }
        public static void Apply(ConversionContent content,IEnumerable<string> selected)
        {
            var ids=Selection(selected);if(ids.Length==0)return;
            var chips=Chips().Where(c=>ids.Any(id=>c.id.StartsWith("rounds-"+id+":",StringComparison.Ordinal))).ToArray();
            NativeRoundsCards.Append(content,chips,"rounds-packs|"+Version+"|"+string.Join(",",ids));
        }
    }
